style.css:
@-moz-document domain("yandex.com"), domain("yandex.ru") {
/* Hide sidebar, ads, and extra widgets */
    .main__aside, .serp-adv, .search3sn__aside, .footer, .b-region__footer {
        display: none !important;
    }

    /* Center search bar */
    .input__control {
        width: 500px !important;
        margin: 50px auto !important;
        display: block !important;
    }

    /* Replace Yandex logo with Google logo */
    .logo__image {
        background-image: url('https://www.google.com/images/branding/googlelogo/2x/googlelogo_color_92x30dp.png') !important;
        width: 92px;
        height: 30px;
    }
}
